B=[['拉丁 tardus','慢的；迟的']]
T=B+[['晚期拉丁 tardivus → 法语 tardif','缓慢、迟到的'],['早期英语 tardive 等形式 → tardy','迟到的；迟缓的']]
R=B+[['拉丁 re- + tardare → retardare','往后拖，使变慢'],['法语 retarder → 英语 retard','延缓；阻碍进展']]
W=[
E('tardy','英 /ˈtɑːdi/；美 /ˈtɑːrdi/','迟到的；迟缓的；来得晚的','大家该到的已经到了、该做的已经做了，你却慢了一拍。','经法语 tardif、晚期拉丁 tardivus 接 tardus 慢；英语早期有 tardive 等形式，后来成为 tardy。',T,'be tardy for class 是上课迟到；a tardy response 是来得太迟的回应。它常带“超过应有时间”的意味，不只是客观描述动作速度慢。','tardy for class；a tardy response；tardy in replying。','late 最通用；tardy 较正式，美式学校出勤语境也常见。slow 说速度慢，未必已经迟到。',('He was marked tardy after arriving ten minutes after the bell.','他在铃响十分钟后才到，被记为迟到。'),('The company gave a tardy response to the complaints.','公司迟迟才对投诉作出回应。'),sources=['https://en.wiktionary.org/wiki/tardy','https://www.etymonline.com/word/tardy']),
E('tardiness','英 /ˈtɑːdinəs/；美 /ˈtɑːrdinəs/','迟到；拖延；迟缓','把一次次慢到、晚做的表现，合起来称作迟到或迟缓的问题。','tardy + -ness，y 改 i；把迟到、迟缓这一性质或行为变成名词。',T+[['tardy + -ness → tardiness','迟到或迟缓的状态']],'repeated tardiness 是反复迟到；the tardiness of a reply 是回复拖得太晚。它通常不可数；统计具体次数时可说 instances of tardiness，而不是一味给它加复数。','repeated tardiness；habitual tardiness；tardiness in responding。','tardiness 侧重到得晚或行动晚；slowness 侧重过程速度慢。一个人操作很慢，但提前出发，仍可能没有 tardiness。',('Repeated tardiness disrupted the morning meetings.','反复迟到打乱了早会安排。'),('She apologized for her tardiness in answering the letter.','她为迟迟没有回信而道歉。'),sources=['https://en.wiktionary.org/wiki/tardiness']),
E('retard','动词：英 /rɪˈtɑːd/；美 /rɪˈtɑːrd/','使减慢；延缓；阻碍〔正式〕','给原本往前走的过程加一点阻力，让它推进得更慢。','来自法语 retarder，接拉丁 re- 往后 + tardare 使慢；核心是拖慢进程。',R,'retard growth 是延缓生长；retard progress 是拖慢进展。动词多见于技术或正式文章，日常说 slow down 更自然。另有重音在前的侮辱性名词用法，不能拿来称呼人。','retard growth；retard progress；retard the spread of something。','retard 是减慢，未必完全停止。delay 更常突出时间往后推。描述人时尤其要区分这里的技术动词与冒犯性的名词。',('Low temperatures can retard the growth of some plants.','低温会使某些植物生长得更慢。'),('A lack of spare parts retarded the repair work.','缺少备件拖慢了维修进度。'),sources=['https://en.wiktionary.org/wiki/retard','https://www.etymonline.com/word/retard']),
E('retarded','英 /rɪˈtɑːdɪd/；美 /rɪˈtɑːrdɪd/','被减慢的；受延缓的；用于人的旧义今属冒犯性用语','在技术句子里，表示一个过程被拖慢；用于人时，词的历史已经带来很不同的语气。','retard + -ed；原先只是被延缓，后来进入旧医学与教育用语，又发展出侮辱性用法。',R+[['retard + -ed → retarded','被拖慢的'],['部分历史人物描述用法发生贬义化','旧称呼及冒犯性用语']],'growth was retarded 是生长受到延缓；这里是普通动词被动式。旧资料把 retarded 用作智力障碍的标签，现代不宜这样称呼人，通常用 intellectual disability 等准确表述。','技术语境：be retarded by；growth was retarded。阅读旧文时识别其过时人物标签。','不能把所有出现 retarded 的句子都当成骂人，也不能把它当作 harmless 的“慢一点”。判断它是在说过程被延缓，还是用来给人贴标签。',('The setting of the concrete was retarded by the additive.','这种添加剂延缓了混凝土的凝结。'),('The editor replaced the outdated label “retarded” with more precise language.','编辑用更准确的表达替换了“retarded”这个过时标签。'),sources=['https://en.wiktionary.org/wiki/retarded','https://dictionary.cambridge.org/us/dictionary/english/retarded']),
E('retardation','英 /ˌriːtɑːˈdeɪʃən/；美 /ˌriːtɑːrˈdeɪʃən/','延缓；减速；阻滞〔正式或技术用语〕','强调进程被拖慢这件事本身，可以讨论慢了多少、由什么造成。','借自拉丁 retardatio，来自 retardare 使慢；有独立的拉丁名词借入链，不只是现代英语动词加后缀。',B+[['拉丁 retardare → retardatio','使慢 → 延缓这一过程'],['英语 retardation','延缓、阻滞；技术领域有具体用法']],'the retardation of growth 指生长受抑或变慢；物理、材料等学科也会在特定意义上使用。旧短语 mental retardation 现多改为 intellectual disability，阅读历史材料时要识别时代差别。','growth retardation；retardation of a process；technical uses of retardation。','retardation 的延缓义并不一概过时；用于智力障碍的旧名称则需要换成现代准确称呼。不要把两类场景混成一个判断。',('The experiment measured the retardation of the reaction at lower temperatures.','实验测量了低温下反应被减慢的程度。'),('The paper discusses the retardation of plant growth under poor conditions.','论文讨论了不良条件下植物生长受到延缓的情况。'),sources=['https://www.etymonline.com/word/retardation','https://www.dictionary.com/browse/retardation','https://medlineplus.gov/ency/article/001523.htm']),
E('retardant','英 /rɪˈtɑːdənt/；美 /rɪˈtɑːrdənt/','阻滞剂；阻燃剂；起延缓作用的','给一个过程设一道减速带，让火势或其他反应不那么容易往前发展。','借自法语 retardant，与 retarder 延缓的分词形式有关；现代也能按 retard + -ant 理解为起阻滞作用的。',R+[['法语 retardant → 英语 retardant','起延缓作用的；延缓用的物质']],'fire retardant 常指阻燃或延缓火势的材料、药剂；也能作形容词描述有这种作用的东西。核心是降低发展速度或抑制燃烧，不应仅凭这个词就认定完全不会着火。','fire retardant；flame retardant；a chemical retardant。','retardant 强调阻滞作用；retardation 是过程；retard 是动词。具体材料的防火性能还得看条件和指标。',('The crew applied a fire retardant around the threatened area.','作业人员在受威胁区域周边施用了阻燃剂。'),('The study compares several retardants used in the manufacturing process.','研究比较了制造过程中使用的几种阻滞剂。'),sources=['https://en.wiktionary.org/wiki/retardant','https://www.merriam-webster.com/dictionary/retardant'])
]
ROOT=dict(id='C1472',meaning='慢；迟；延缓',core='TARD = SLOW / LATE',image='一条向前走的队伍里，有人晚到一步，是 tardy；如果路上多了阻力，整个队伍被拖慢，就是 retard 的画面。',intro='来自拉丁 tardus“缓慢、迟”。tardy 侧重晚于应到时间；retard 侧重让进程变慢。词源提供共同画面，但人物称呼、技术术语和日常表达各有自己的语气。',forms='tardy 经法语 tardif 进入，tardiness 在英语中加后缀。retard 接拉丁 retardare 经法语传入；retardation 有独立拉丁名词来源。tardigrade 的后一部分表示行走，原名有缓慢行走之意。',branches=[['到得晚、做得晚','tardy, tardiness'],['让进程慢下来','retard, retarded, retardation, retardant'],['缓慢行走的动物名称','tardigrade']],contrasts='迟到不等于动作慢。retard 的技术动词义可正常理解；retarded 给人贴标签的用法已过时且冒犯。retardant 说阻滞，不等于在任何条件下完全阻止。',practice='The tardy delivery of parts retarded the repair work.\n\n零件交付晚了，拖慢了维修进度。',words=[x['word'] for x in W]+['tardigrade'],exclude={})
